<script lang="ts">
  import { onMount } from 'svelte';

  interface Props {
    class?: string;
    width?: number | string;
    height?: number | string;
  }

  let { class: className = '', width = 130, height = 130 }: Props = $props();

  let svgEl: SVGSVGElement | null = null;

  onMount(() => {
    // Only rewind the animation if restored from browser back/forward cache (bfcache).
    // Never reset on initial hydration, because the browser already began playing
    // the inline SVG animation immediately on HTML parse; resetting here would cause
    // the animation to glitch and restart mid-way on slower connections.
    const onPageShow = (e: PageTransitionEvent) => {
      if (e.persisted && svgEl && typeof svgEl.setCurrentTime === 'function') {
        try {
          svgEl.setCurrentTime(0);
        } catch {
          // Ignore
        }
      }
    };

    window.addEventListener('pageshow', onPageShow);
    return () => {
      window.removeEventListener('pageshow', onPageShow);
    };
  });
</script>

